import sys

def reverse_num(n):
    return int(str(n)[::-1])

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    n = int(line)
    steps = 0
    found = False
    while steps <= 60:
        if str(n) == str(n)[::-1]:
            found = True
            break
        n = n + reverse_num(n)
        steps += 1
    if found:
        print(steps, n)
    else:
        print("Palindrome not found.")

