import sys

FACT = [1] * 10
for i in range(1, 10):
    FACT[i] = FACT[i - 1] * i

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    n = int(line)
    if n == 0:
        break
    total = sum(FACT[int(d)] for d in str(n))
    if total == n:
        print(f"{n} is a Strong Number.")
    else:
        print(f"{n} is not a Strong Number.")

