import sys

for raw in sys.stdin:
    raw = raw.rstrip('\n')
    if not raw.strip():
        continue
    k_str, text = raw.split(' ', 1)
    k = int(k_str)
    out = []
    for c in text:
        if 'a' <= c <= 'z':
            out.append(chr((ord(c) - ord('a') - k) % 26 + ord('a')))
        elif 'A' <= c <= 'Z':
            out.append(chr((ord(c) - ord('A') - k) % 26 + ord('A')))
        else:
            out.append(c)
    print(''.join(out))

