import sys

data = sys.stdin.read().split('\n')
idx = 0
out = []
while idx < len(data):
    line = data[idx].strip()
    idx += 1
    if line == '':
        continue
    n = int(line)
    if n == 0:
        break
    words = []
    for _ in range(n):
        words.append(data[idx])
        idx += 1
    prefix = words[0]
    for w in words[1:]:
        while not w.startswith(prefix):
            prefix = prefix[:-1]
            if prefix == '':
                break
        if prefix == '':
            break
    if prefix == '':
        out.append("No common prefix.")
    else:
        out.append(prefix)
print('\n'.join(out))

