import sys

def divisor_sum(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i != n:
                total += i
            j = n // i
            if j != i and j != n:
                total += j
        i += 1
    return total

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    n = int(line)
    if n == 0:
        break
    if divisor_sum(n) == n:
        print(f"{n} is a perfect number.")
    else:
        print(f"{n} is not a perfect number.")

