import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        s = int(data[idx]); d = int(data[idx + 1]); idx += 2

        def cum_days(k):
            return k * s + k * (k - 1) // 2

        lo, hi = 0, 2 * 10 ** 8
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if cum_days(mid) < d:
                lo = mid
            else:
                hi = mid - 1
        out.append(str(s + lo))
    print('\n'.join(out))

main()

