                seenset.add(ch)
                seen.append(ch)
        return sorted(seen, key=lambda c: -counter[c])

    for case in range(t):
        while data[idx].strip() == '':
            idx += 1
        plain = data[idx]; idx += 1
        enc = data[idx]; idx += 1
        p_order = ranked(plain, Counter(plain))
        e_order = ranked(enc, Counter(enc))
        mapping = dict(zip(e_order, p_order))
        if case > 0:
            out.append('')
        out.append(''.join(mapping.get(c, c) for c in enc))
    print('\n'.join(out))

main()

import sys

def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums = list(map(int, line.split()))
        n_tape = nums[0]
        cnt = nums[1]
        tracks = nums[2:2 + cnt]
        reachable = {0: 0}
        for i, t in enumerate(tracks):
            for s in list(reachable.keys()):
                ns = s + t
                if ns <= n_tape and ns not in reachable:
                    reachable[ns] = reachable[s] | (1 << i)
        best_sum = max(reachable.keys())
        best_mask = reachable[best_sum]
        chosen = [tracks[i] for i in range(cnt) if best_mask & (1 << i)]
        out.append(' '.join(map(str, chosen)) + f" sum:{best_sum}")
    print('\n'.join(out))

