import sys

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        r, c = map(int, line.split())
        if r == 0 and c == 0:
            break
        grid = [data[idx + i] for i in range(r)]
        idx += r
        visited = [[False] * c for _ in range(r)]

        def flood(si, sj):
            stack = [(si, sj)]
            visited[si][sj] = True
            while stack:
                x, y = stack.pop()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < r and 0 <= ny < c and not visited[nx][ny] and grid[nx][ny] == '1':
                        visited[nx][ny] = True
                        stack.append((nx, ny))

        count = 0
        for i in range(r):
            for j in range(c):
                if grid[i][j] == '1' and not visited[i][j]:
                    count += 1
                    flood(i, j)
        out.append(str(count))
    print('\n'.join(out))

main()

