import sys
import math

def solve(n):
    if n == 1:
        return (1, 1)
    r = math.isqrt(n - 1) + 1
    while r * r < n:
        r += 1
    start = (r - 1) ** 2 + 1
    offset = n - start
    if r % 2 == 0:
        if offset <= r - 1:
            x, y = 1 + offset, r
        else:
            off2 = offset - r
            x, y = r, r - 1 - off2
    else:
        if offset <= r - 1:
            x, y = r, 1 + offset
        else:
            off2 = offset - r
            x, y = r - 1 - off2, r
    return x, y

def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        if n == 0:
            break
        x, y = solve(n)
        out.append(f"{x} {y}")
    print('\n'.join(out))

main()

