import sys

def fib_pair(k, m):
    if k == 0:
        return (0, 1)
    a, b = fib_pair(k >> 1, m)
    c = (a * ((2 * b - a) % m)) % m
    d = (a * a + b * b) % m
    if k & 1:
        return (d, (c + d) % m)
    return (c, d)

def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n, mexp = map(int, line.split())
        m = 1 << mexp
        out.append(str(fib_pair(n, m)[0] if m > 1 else 0))
    print('\n'.join(out))

