import itertools

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    ops = ['+', '-', '*']
    while idx < len(data):
        nums = [int(data[idx + i]) for i in range(5)]
        idx += 5
        if nums == [0, 0, 0, 0, 0]:
            break
        found = False
        for perm in itertools.permutations(nums):
            for opcombo in itertools.product(ops, repeat=4):
                val = perm[0]
                for i in range(4):
                    if opcombo[i] == '+':
                        val += perm[i + 1]
                    elif opcombo[i] == '-':
                        val -= perm[i + 1]
                    else:
                        val *= perm[i + 1]
                if val == 23:
                    found = True
                    break
            if found:
                break
        out.append('Possible' if found else 'Impossible')
    print('\n'.join(out))

