        inc = [1] * n
        dec = [1] * n
        for i in range(n):
            for j in range(i):
                if a[j] < a[i]:
                    inc[i] = max(inc[i], inc[j] + 1)
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
