    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        result = n
        x = n
        p = 2
        while p * p <= x:
            if x % p == 0:
                while x % p == 0:
                    x //= p
                result -= result // p
            p += 1
        if x > 1:
            result -= result // x
        out.append(str(result))
