def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        r = int(data[idx]); c = int(data[idx + 1]); idx += 2
        if r == 0 and c == 0:
            break
        grid = []
        for i in range(r):
            grid.append([int(data[idx + j]) for j in range(c)])
            idx += c
        best = None
        for top in range(r):
            colsum = [0] * c
            for bottom in range(top, r):
                for j in range(c):
                    colsum[j] += grid[bottom][j]
                cur = colsum[0]
                mx = colsum[0]
                for j in range(1, c):
                    cur = max(colsum[j], cur + colsum[j])
                    mx = max(mx, cur)
                if best is None or mx > best:
                    best = mx
        out.append(str(best))
    print('\n'.join(out))

