def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        n = int(line)
        words = []
        for _ in range(n):
            words.append(data[idx].strip()); idx += 1
        q = int(data[idx].strip()); idx += 1
        trie = {}
        for w in words:
            node = trie
            for c in w:
                node = node.setdefault(c, {'#': 0})
                node['#'] += 1
        for _ in range(q):
            prefix = data[idx].strip(); idx += 1
            node = trie
            cnt = 0
            ok = True
            for c in prefix:
                if c not in node:
                    ok = False
                    break
                node = node[c]
            if ok:
                cnt = node['#']
            out.append(str(cnt))
    print('\n'.join(out))

