import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, i, delta):
        while i <= self.n:
            self.tree[i] += delta
            i += i & (-i)

    def query(self, i):
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & (-i)
        return s

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    case = 0
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        n = int(line)
        if n == 0:
            break
        case += 1
        vals = [0] * (n + 1)
        bit = BIT(n)
        for i in range(1, n + 1):
            v = int(data[idx].strip()); idx += 1
            vals[i] = v
            bit.update(i, v)
        if case > 1:
            out.append('')
        out.append(f"Case {case}:")
        while True:
            parts = data[idx].split(); idx += 1
            if parts[0] == 'END':
                break
            if parts[0] == 'S':
                x, r = int(parts[1]), int(parts[2])
                delta = r - vals[x]
                vals[x] = r
                bit.update(x, delta)
            else:
                x, y = int(parts[1]), int(parts[2])
                out.append(str(bit.query(y) - bit.query(x - 1)))
    print('\n'.join(out))

main()

