import sys

def z_function(s):
    n = len(s)
    z = [0] * n
    l = r = 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return z

def main():
    out = []
    for line in sys.stdin:
        line = line.rstrip('\n')
        if not line:
            continue
        text, pattern = line.split()
        combined = pattern + '#' + text
        z = z_function(combined)
        count = sum(1 for v in z[len(pattern) + 1:] if v >= len(pattern))
        out.append(str(count))
    print('\n'.join(out))

main()

