import sys
from collections import OrderedDict

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        cap = int(line)
        if cap == 0:
            break
        cache = OrderedDict()
        q = int(data[idx].strip()); idx += 1
        for _ in range(q):
            parts = data[idx].split(); idx += 1
            if parts[0] == 'PUT':
                k, v = int(parts[1]), int(parts[2])
                if k in cache:
                    del cache[k]
                cache[k] = v
                if len(cache) > cap:
                    cache.popitem(last=False)
            else:
                k = int(parts[1])
                if k in cache:
                    v = cache.pop(k)
                    cache[k] = v
                    out.append(str(v))
                else:
                    out.append('-1')
    print('\n'.join(out))

main()

