import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        vals = [int(data[idx + i]) for i in range(n)]
        idx += n
        tree = {}
        root = None
        for v in vals:
            if root is None:
                root = v
                tree[v] = [None, None]
                continue
            node = root
            while True:
                if v < node:
                    if tree[node][0] is None:
                        tree[node][0] = v
                        tree[v] = [None, None]
                        break
                    node = tree[node][0]
                else:
                    if tree[node][1] is None:
                        tree[node][1] = v
                        tree[v] = [None, None]
                        break
                    node = tree[node][1]
        result = []

        def inorder(node):
            if node is None:
                return
            inorder(tree[node][0])
            result.append(node)
            inorder(tree[node][1])

        inorder(root)
        out.append(' '.join(map(str, result)))
    print('\n'.join(out))

main()

