def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n = int(line)
        results = []

        def backtrack(s, open_cnt, close_cnt):
            if len(s) == 2 * n:
                results.append(s)
                return
            if open_cnt < n:
                backtrack(s + '(', open_cnt + 1, close_cnt)
            if close_cnt < open_cnt:
                backtrack(s + ')', open_cnt, close_cnt + 1)

        backtrack('', 0, 0)
        out.append(' '.join(results))
    print('\n'.join(out))

