import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        parent = [int(data[idx + i]) for i in range(n)]
        idx += n
        children = [[] for _ in range(n)]
        root = -1
        for i, p in enumerate(parent):
            if p == -1:
                root = i
            else:
                children[p].append(i)

        def height(u):
            if not children[u]:
                return 1
            return 1 + max(height(v) for v in children[u])

        out.append(str(height(root)))
    print('\n'.join(out))

main()

