def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        q = int(line)
        if q == 0:
            break
        stack = []
        minstack = []
        for _ in range(q):
            parts = data[idx].split(); idx += 1
            cmd = parts[0]
            if cmd == 'PUSH':
                x = int(parts[1])
                stack.append(x)
                minstack.append(x if not minstack or x <= minstack[-1] else minstack[-1])
            elif cmd == 'POP':
                stack.pop()
                minstack.pop()
            elif cmd == 'TOP':
                out.append(str(stack[-1]))
            elif cmd == 'GETMIN':
                out.append(str(minstack[-1]))
    print('\n'.join(out))

