import sys

PREC = {'+': 1, '-': 1, '*': 2, '/': 2}

def main():
    out = []
    for line in sys.stdin:
        tokens = line.strip().split()
        if not tokens:
            continue
        output = []
        ops = []
        for tok in tokens:
            if tok not in PREC and tok not in '()':
                output.append(tok)
            elif tok == '(':
                ops.append(tok)
            elif tok == ')':
                while ops and ops[-1] != '(':
                    output.append(ops.pop())
                ops.pop()
            else:
                while ops and ops[-1] != '(' and PREC[ops[-1]] >= PREC[tok]:
                    output.append(ops.pop())
                ops.append(tok)
        while ops:
            output.append(ops.pop())
        out.append(' '.join(output))
    print('\n'.join(out))

main()

