def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        n = len(s)
        dp = [[0] * (n + 1) for _ in range(n + 1)]
        best = 0
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if i != j and s[i - 1] == s[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    if dp[i][j] <= abs(i - j):
                        best = max(best, dp[i][j])
                else:
                    dp[i][j] = 0
        out.append(str(best))
    print('\n'.join(out))

