            adj[v].append(u)
        disc = [-1] * n
        low = [0] * n
        is_art = [False] * n
        timer = [0]

        def dfs(u, parent):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            children = 0
            for v in adj[u]:
                if v == parent:
                    continue
                if disc[v] == -1:
                    children += 1
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if parent != -1 and low[v] >= disc[u]:
                        is_art[u] = True
                else:
                    low[u] = min(low[u], disc[v])
            if parent == -1 and children > 1:
                is_art[u] = True

        for i in range(n):
            if disc[i] == -1:
                dfs(i, -1)
        result = sorted(i for i in range(n) if is_art[i])
        out.append(' '.join(map(str, result)) if result else 'none')
    print('\n'.join(out))

main()

