import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); m = int(data[idx + 1]); idx += 2
        if n == 0 and m == 0:
            break
        adj = [[] for _ in range(n)]
        radj = [[] for _ in range(n)]
        for _ in range(m):
            u = int(data[idx]); v = int(data[idx + 1]); idx += 2
            adj[u].append(v)
            radj[v].append(u)
        visited = [False] * n
        order = []

        def dfs1(start):
            stack = [(start, iter(adj[start]))]
            visited[start] = True
            while stack:
                node, it = stack[-1]
                advanced = False
                for v in it:
                    if not visited[v]:
                        visited[v] = True
                        stack.append((v, iter(adj[v])))
                        advanced = True
                        break
                if not advanced:
                    order.append(node)
                    stack.pop()

        for i in range(n):
            if not visited[i]:
                dfs1(i)

        comp = [-1] * n
        cid = 0
        for u in reversed(order):
            if comp[u] == -1:
                stack = [u]
                comp[u] = cid
                while stack:
                    node = stack.pop()
                    for v in radj[node]:
                        if comp[v] == -1:
                            comp[v] = cid
                            stack.append(v)
                cid += 1
        out.append(str(cid))
    print('\n'.join(out))

