import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        if data[idx] == 'END':
            break
        grid = [[int(data[idx + i * 9 + j]) for j in range(9)] for i in range(9)]
        idx += 81

        def valid(r, c, v):
            for i in range(9):
                if grid[r][i] == v or grid[i][c] == v:
                    return False
            br, bc = 3 * (r // 3), 3 * (c // 3)
            for i in range(br, br + 3):
                for j in range(bc, bc + 3):
                    if grid[i][j] == v:
                        return False
            return True

        def solve():
            for r in range(9):
                for c in range(9):
                    if grid[r][c] == 0:
                        for v in range(1, 10):
                            if valid(r, c, v):
                                grid[r][c] = v
                                if solve():
                                    return True
                                grid[r][c] = 0
                        return False
            return True

        solve()
        for row in grid:
            out.append(''.join(map(str, row)))
    print('\n'.join(out))

main()

