def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            out.append('0')
            continue
        n = len(s)
        is_pal = [[False] * n for _ in range(n)]
        for i in range(n):
            is_pal[i][i] = True
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j] and (length == 2 or is_pal[i + 1][j - 1]):
                    is_pal[i][j] = True
        cuts = [0] * n
        for i in range(n):
            if is_pal[0][i]:
                cuts[i] = 0
                continue
            best = i
            for j in range(1, i + 1):
                if is_pal[j][i]:
                    best = min(best, cuts[j - 1] + 1)
            cuts[i] = best
        out.append(str(cuts[n - 1]))
    print('\n'.join(out))

