from collections import deque

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        parts = line.split()
        if parts[0] == '0':
            break
        begin, end = parts[0], parts[1]
        n = int(data[idx].strip()); idx += 1
        words = set()
        for _ in range(n):
            words.add(data[idx].strip()); idx += 1
        words.discard(begin)
        q = deque([(begin, 1)])
        visited = {begin}
        found = 0
        while q:
            word, steps = q.popleft()
            if word == end:
                found = steps
                break
            for i in range(len(word)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    if c == word[i]:
                        continue
                    nw = word[:i] + c + word[i + 1:]
                    if nw in words and nw not in visited:
                        visited.add(nw)
                        q.append((nw, steps + 1))
        out.append(str(found))
    print('\n'.join(out))

main()

