import sys

def mat_mult(a, b, mod):
    n = len(a); k = len(b); m = len(b[0])
    res = [[0] * m for _ in range(n)]
    for i in range(n):
        for x in range(k):
            if a[i][x]:
                for j in range(m):
                    res[i][j] = (res[i][j] + a[i][x] * b[x][j]) % mod
    return res

def mat_pow(mat, p, mod):
    n = len(mat)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    while p > 0:
        if p & 1:
            result = mat_mult(result, mat, mod)
        mat = mat_mult(mat, mat, mod)
        p >>= 1
    return result

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        d = int(data[idx]); n = int(data[idx + 1]); m = int(data[idx + 2]); idx += 3
        if d == 0 and n == 0 and m == 0:
            break
        a = [int(data[idx + i]) for i in range(d)]
        idx += d
        f = [int(data[idx + i]) for i in range(d)]
        idx += d
        if n <= d:
            out.append(str(f[n - 1] % m))
            continue
        trans = [[0] * d for _ in range(d)]
        for j in range(d):
            trans[0][j] = a[j] % m
        for i in range(1, d):
            trans[i][i - 1] = 1
        mp = mat_pow(trans, n - d, m)
        base = list(reversed(f))
        res = 0
        for j in range(d):
            res = (res + mp[0][j] * base[j]) % m
        out.append(str(res % m))
    print('\n'.join(out))

main()

import sys

def mat_mult(a, b, mod):
    n = len(a); k = len(b); m = len(b[0])
    res = [[0] * m for _ in range(n)]
    for i in range(n):
        for x in range(k):
            if a[i][x]:
                for j in range(m):
                    res[i][j] = (res[i][j] + a[i][x] * b[x][j]) % mod
    return res

def mat_pow(mat, p, mod):
    n = len(mat)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    while p > 0:
        if p & 1:
            result = mat_mult(result, mat, mod)
        mat = mat_mult(mat, mat, mod)
        p >>= 1
    return result

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        d = int(data[idx]); n = int(data[idx + 1]); m = int(data[idx + 2]); idx += 3
        if d == 0 and n == 0 and m == 0:
            break
        a = [int(data[idx + i]) for i in range(d)]
        idx += d
        f = [int(data[idx + i]) for i in range(d)]
        idx += d
        if n <= d:
            out.append(str(f[n - 1] % m))
            continue
        trans = [[0] * d for _ in range(d)]
        for j in range(d):
            trans[0][j] = a[j] % m
        for i in range(1, d):
            trans[i][i - 1] = 1
        mp = mat_pow(trans, n - d, m)
        base = list(reversed(f))
        res = 0
        for j in range(d):
            res = (res + mp[0][j] * base[j]) % m
        out.append(str(res % m))
    print('\n'.join(out))

main()

import sys
from collections import deque

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    t = int(data[idx].strip()); idx += 1
    out = []
    for _ in range(t):
        while data[idx].strip() == '':
            idx += 1
        r, c = map(int, data[idx].split()); idx += 1
        grid = [data[idx + i] for i in range(r)]
        idx += r
        fire_time = [[-1] * c for _ in range(r)]
        joe_time = [[-1] * c for _ in range(r)]
        fq = deque()
        jstart = None
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 'F':
                    fire_time[i][j] = 0
                    fq.append((i, j))
                elif grid[i][j] == 'J':
                    jstart = (i, j)
        while fq:
            x, y = fq.popleft()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] != '#' and fire_time[nx][ny] == -1:
                    fire_time[nx][ny] = fire_time[x][y] + 1
                    fq.append((nx, ny))
        jq = deque([jstart])
        joe_time[jstart[0]][jstart[1]] = 0
        answer = -1
        while jq:
            x, y = jq.popleft()
            if x == 0 or x == r - 1 or y == 0 or y == c - 1:
                answer = joe_time[x][y] + 1
                break
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < r and 0 <= ny < c and grid[nx][ny] != '#' and joe_time[nx][ny] == -1:
                    nt = joe_time[x][y] + 1
                    if fire_time[nx][ny] == -1 or nt < fire_time[nx][ny]:
                        joe_time[nx][ny] = nt
                        jq.append((nx, ny))
        out.append(str(answer) if answer != -1 else 'IMPOSSIBLE')
    print('\n'.join(out))

main()

