import sys
import heapq

def main():
    sys.setrecursionlimit(10000)
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        m = int(data[idx]); idx += 1
        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            a = int(data[idx]); b = int(data[idx + 1]); d = int(data[idx + 2]); idx += 3
            adj[a].append((b, d))
            adj[b].append((a, d))
        INF = float('inf')
        dist = [INF] * (n + 1)
        dist[2] = 0
        pq = [(0, 2)]
        while pq:
            dd, u = heapq.heappop(pq)
            if dd > dist[u]:
                continue
            for v, w in adj[u]:
                if dd + w < dist[v]:
                    dist[v] = dd + w
                    heapq.heappush(pq, (dist[v], v))
        memo = {}

        def count(u):
            if u == 2:
                return 1
            if u in memo:
                return memo[u]
            total = 0
            for v, w in adj[u]:
                if dist[v] < dist[u]:
                    total += count(v)
            memo[u] = total
            return total

        out.append(str(count(1)))
    print('\n'.join(out))

main()

