def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); m = int(data[idx + 1]); e = int(data[idx + 2]); idx += 3
        if n == 0 and m == 0 and e == 0:
            break
        adj = [[] for _ in range(n)]
        for _ in range(e):
            u = int(data[idx]); v = int(data[idx + 1]); idx += 2
            adj[u].append(v)
        match_r = [-1] * m

        def try_match(u, visited):
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    if match_r[v] == -1 or try_match(match_r[v], visited):
                        match_r[v] = u
                        return True
            return False

        result = 0
        for u in range(n):
            visited = [False] * m
            if try_match(u, visited):
                result += 1
        out.append(str(result))
    print('\n'.join(out))

