def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        val, left, right = [], [], []
        for _ in range(n):
            val.append(int(data[idx])); left.append(int(data[idx + 1])); right.append(int(data[idx + 2])); idx += 3

        def check(u, lo, hi):
            if u == -1:
                return True
            if not (lo < val[u] < hi):
                return False
            return check(left[u], lo, val[u]) and check(right[u], val[u], hi)

        out.append('Yes' if check(0, float('-inf'), float('inf')) else 'No')
    print('\n'.join(out))

