def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        n, k = map(int, line.split())
        if n == 0 and k == 0:
            break
        if n == 1:
            out.append(str(k))
            continue
        same, diff = k, k * (k - 1)
        for _ in range(3, n + 1):
            same, diff = diff, (same + diff) * (k - 1)
        out.append(str(same + diff))
    print('\n'.join(out))

