def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); target = int(data[idx + 1]); idx += 2
        if n == 0 and target == 0:
            break
        a = sorted(int(data[idx + i]) for i in range(n))
        idx += n
        best = a[0] + a[1] + a[2]
        for i in range(n - 2):
            l, r = i + 1, n - 1
            while l < r:
                s = a[i] + a[l] + a[r]
                if abs(s - target) < abs(best - target):
                    best = s
                if s == target:
                    break
                elif s < target:
                    l += 1
                else:
                    r -= 1
        out.append(str(best))
    print('\n'.join(out))

