import sys

def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        results = []

        def backtrack(start, path):
            if start == len(s):
                results.append('|'.join(path))
                return
            for end in range(start + 1, len(s) + 1):
                piece = s[start:end]
                if piece == piece[::-1]:
                    path.append(piece)
                    backtrack(end, path)
                    path.pop()

        backtrack(0, [])
        out.append(str(len(results)))
        out.extend(results)
    print('\n'.join(out))

