from collections import deque

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        n = int(line)
        if n == 0:
            break
        grid = []
        for _ in range(n):
            grid.append(list(map(int, data[idx].split())))
            idx += 1
        if grid[0][0] == 1 or grid[n - 1][n - 1] == 1:
            out.append('-1')
            continue
        dist = [[-1] * n for _ in range(n)]
        dist[0][0] = 1
        q = deque([(0, 0)])
        while q:
            x, y = q.popleft()
            if x == n - 1 and y == n - 1:
                break
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    if dx == 0 and dy == 0:
                        continue
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0 and dist[nx][ny] == -1:
                        dist[nx][ny] = dist[x][y] + 1
                        q.append((nx, ny))
        out.append(str(dist[n - 1][n - 1]))
    print('\n'.join(out))

