import sys

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        n = int(line)
        if n == 0:
            break
        trie = {}
        for _ in range(n):
            w = data[idx].strip(); idx += 1
            node = trie
            for c in w:
                node = node.setdefault(c, {})
            node['$'] = True
        q = int(data[idx].strip()); idx += 1

        def search(word):
            def dfs(node, pos):
                if pos == len(word):
                    return '$' in node
                c = word[pos]
                if c == '.':
                    return any(dfs(child, pos + 1) for k, child in node.items() if k != '$')
                if c not in node:
                    return False
                return dfs(node[c], pos + 1)
            return dfs(trie, 0)

        for _ in range(q):
            w = data[idx].strip(); idx += 1
            out.append('Yes' if search(w) else 'No')
    print('\n'.join(out))

main()

