import sys
from collections import deque

def main():
    data = sys.stdin.read().split('\n')
    idx = 0
    out = []
    while idx < len(data):
        line = data[idx].strip(); idx += 1
        if line == '':
            continue
        cap = int(line)
        if cap == 0:
            break
        dq = deque()
        q = int(data[idx].strip()); idx += 1
        for _ in range(q):
            parts = data[idx].split(); idx += 1
            cmd = parts[0]
            if cmd == 'PUSH_FRONT':
                if len(dq) < cap:
                    dq.appendleft(int(parts[1]))
                    out.append('true')
                else:
                    out.append('false')
            elif cmd == 'PUSH_BACK':
                if len(dq) < cap:
                    dq.append(int(parts[1]))
                    out.append('true')
                else:
                    out.append('false')
            elif cmd == 'POP_FRONT':
                if dq:
                    dq.popleft()
                    out.append('true')
                else:
                    out.append('false')
            elif cmd == 'POP_BACK':
                if dq:
                    dq.pop()
                    out.append('true')
                else:
                    out.append('false')
            elif cmd == 'FRONT':
                out.append(str(dq[0]) if dq else '-1')
            elif cmd == 'BACK':
                out.append(str(dq[-1]) if dq else '-1')
    print('\n'.join(out))

