import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        vals = [int(data[idx + i]) for i in range(n)]
        idx += n
        target = int(data[idx]); idx += 1
        tree = {}
        root = None
        for v in vals:
            if root is None:
                root = v
                tree[v] = [None, None]
                continue
            node = root
            while True:
                if v < node:
                    if tree[node][0] is None:
                        tree[node][0] = v
                        tree[v] = [None, None]
                        break
                    node = tree[node][0]
                else:
                    if tree[node][1] is None:
                        tree[node][1] = v
                        tree[v] = [None, None]
                        break
                    node = tree[node][1]

        def delete(node, val):
            if node is None:
                return None
            if val < node:
                tree[node][0] = delete(tree[node][0], val)
                return node
            if val > node:
                tree[node][1] = delete(tree[node][1], val)
                return node
            if tree[node][0] is None:
                return tree[node][1]
            if tree[node][1] is None:
                return tree[node][0]
            succ = tree[node][1]
            while tree[succ][0] is not None:
                succ = tree[succ][0]
            tree[node][1] = delete(tree[node][1], succ)
            tree[succ] = tree[node]
            return succ

        root = delete(root, target)
        result = []

        def inorder(u):
            if u is None:
                return
            inorder(tree[u][0])
            result.append(u)
            inorder(tree[u][1])

        inorder(root)
        out.append(' '.join(map(str, result)))
    print('\n'.join(out))

main()

