import sys
import heapq
from collections import defaultdict

def main():
    words = []
    for line in sys.stdin:
        line = line.strip()
        if line == '#':
            break
        if line:
            words.append(line)
    adj = defaultdict(set)
    letters = set()
    for w in words:
        letters.update(w)
    for i in range(len(words) - 1):
        a, b = words[i], words[i + 1]
        for x, y in zip(a, b):
            if x != y:
                adj[x].add(y)
                break
    indeg = {c: 0 for c in letters}
    for u in adj:
        for v in adj[u]:
            indeg[v] += 1
    heap = [c for c in letters if indeg[c] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    print(''.join(order))

main()

