def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        max_a = int(line)
        for a in range(2, max_a + 1):
            a3 = a ** 3
            for b in range(2, a):
                b3 = b ** 3
                if b3 >= a3:
                    break
                for c in range(b, a):
                    c3 = c ** 3
                    bc3 = b3 + c3
                    if bc3 >= a3:
                        break
                    d3 = a3 - bc3
                    d = round(d3 ** (1 / 3))
                    for dd in (d - 1, d, d + 1):
                        if dd >= c and dd ** 3 == d3:
                            out.append(f"Cube = {a}, Triple = ({b},{c},{dd})")
                            break
    print('\n'.join(out))

