                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        i, j = n, m
        seq = []
        while i > 0 and j > 0:
            if s1[i - 1] == s2[j - 1]:
                seq.append(s1[i - 1])
