import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); target = int(data[idx + 1]); idx += 2
        if n == 0 and target == 0:
            break
        nums = [int(data[idx + i]) for i in range(n)]
        idx += n
        dp = [[False] * (target + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = True
        for i in range(1, n + 1):
            for t in range(target + 1):
                dp[i][t] = dp[i - 1][t]
                if not dp[i][t] and nums[i - 1] <= t:
                    dp[i][t] = dp[i - 1][t - nums[i - 1]]
        if not dp[n][target]:
            out.append('No')
            continue
        result = []
        t = target
        for i in range(n, 0, -1):
            if not dp[i - 1][t]:
                result.append(nums[i - 1])
                t -= nums[i - 1]
        out.append('Yes')
        out.append(' '.join(map(str, result)))
    print('\n'.join(out))

main()

