def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        val, left, right = [], [], []
        for _ in range(n):
            val.append(int(data[idx])); left.append(int(data[idx + 1])); right.append(int(data[idx + 2])); idx += 3
        count = [0]

        def dfs(u):
            if u == -1:
                return True
            l_ok = dfs(left[u])
            r_ok = dfs(right[u])
            ok = l_ok and r_ok
            if ok and left[u] != -1 and val[left[u]] != val[u]:
                ok = False
            if ok and right[u] != -1 and val[right[u]] != val[u]:
                ok = False
            if ok:
                count[0] += 1
            return ok

        dfs(0)
        out.append(str(count[0]))
    print('\n'.join(out))

