from collections import deque

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        val, left, right = [], [], []
        for _ in range(n):
            val.append(int(data[idx])); left.append(int(data[idx + 1])); right.append(int(data[idx + 2])); idx += 3
        result = []
        q = deque([0])
        while q:
            size = len(q)
            for i in range(size):
                u = q.popleft()
                if i == size - 1:
                    result.append(val[u])
                if left[u] != -1:
                    q.append(left[u])
                if right[u] != -1:
                    q.append(right[u])
        out.append(' '.join(map(str, result)))
    print('\n'.join(out))

