import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        parent = list(range(n + 1))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        ans = None
        for _ in range(n):
            u = int(data[idx]); v = int(data[idx + 1]); idx += 2
            ru, rv = find(u), find(v)
            if ru == rv:
                ans = (u, v)
            else:
                parent[ru] = rv
        out.append(f"{ans[0]} {ans[1]}")
    print('\n'.join(out))

main()

