def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        a = [int(data[idx + i]) for i in range(n)]
        idx += n
        count = 0
        ok = True
        for i in range(1, n):
            if a[i - 1] > a[i]:
                count += 1
                if count > 1:
                    ok = False
