import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    case = 0
    while True:
        a = int(data[idx]); b = int(data[idx + 1]); idx += 2
        if a == -1 and b == -1:
            break
        case += 1
        parent = {}
        indeg = {}
        nodes = set()

        def find(x):
            parent.setdefault(x, x)
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        is_tree = True
        while not (a == 0 and b == 0):
            nodes.add(a); nodes.add(b)
            indeg[b] = indeg.get(b, 0) + 1
            if indeg[b] > 1:
                is_tree = False
            ra, rb = find(a), find(b)
            if ra == rb:
                is_tree = False
            else:
                parent[ra] = rb
            a = int(data[idx]); b = int(data[idx + 1]); idx += 2
        roots = set(find(n) for n in nodes)
        if len(roots) > 1:
            is_tree = False
        out.append(f"Case {case} is a tree." if is_tree else f"Case {case} is not a tree.")
    print('\n'.join(out))

main()

