import sys

def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            dp[i][i] = 1
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
        i, j = 0, n - 1
        left, right = [], []
        while i < j:
            if s[i] == s[j]:
                left.append(s[i])
                right.append(s[j])
                i += 1; j -= 1
            elif dp[i + 1][j] >= dp[i][j - 1]:
                i += 1
            else:
                j -= 1
        mid = s[i] if i == j else ''
        seq = ''.join(left) + mid + ''.join(reversed(right))
        out.append(str(len(seq)))
        out.append(seq)
    print('\n'.join(out))

main()

import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); idx += 1
        if n == 0:
            break
        a = [int(data[idx + i]) for i in range(n)]
        idx += n
        length = [1] * n
        count = [1] * n
        for i in range(n):
            for j in range(i):
                if a[j] < a[i]:
                    if length[j] + 1 > length[i]:
                        length[i] = length[j] + 1
                        count[i] = count[j]
                    elif length[j] + 1 == length[i]:
                        count[i] += count[j]
        best = max(length)
        total = sum(c for l, c in zip(length, count) if l == best)
        out.append(str(total))
    print('\n'.join(out))

main()

