def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); k = int(data[idx + 1]); idx += 2
        if n == 0 and k == 0:
            break
        a = [int(data[idx + i]) for i in range(n)]
        idx += n
        seen = {0: -1}
        cur = 0
        found = False
        for i in range(n):
            cur = (cur + a[i]) % k
            if cur in seen:
                if i - seen[cur] >= 2:
                    found = True
                    break
            else:
                seen[cur] = i
        out.append('Yes' if found else 'No')
    print('\n'.join(out))

main()

