import sys

def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        stack = [['', 1]]
        num = ''
        for c in s:
            if c.isdigit():
                num += c
            elif c == '[':
                stack.append(['', int(num)])
                num = ''
            elif c == ']':
                sub, k = stack.pop()
                stack[-1][0] += sub * k
            else:
                stack[-1][0] += c
        out.append(stack[0][0])
    print('\n'.join(out))

main()

import sys

def is_match(s, p):
    n, m = len(s), len(p)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True
    for j in range(1, m + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]
            elif p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
    return dp[n][m]

def main():
    out = []
    for line in sys.stdin:
        line = line.rstrip('\n')
        if not line:
            continue
        s, p = line.split()
        out.append('Yes' if is_match(s, p) else 'No')
    print('\n'.join(out))

main()

import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); target = int(data[idx + 1]); idx += 2
        if n == 0 and target == 0:
            break
        val, left, right = [], [], []
        for _ in range(n):
            val.append(int(data[idx])); left.append(int(data[idx + 1])); right.append(int(data[idx + 2])); idx += 3
        results = []

        def dfs(u, path, total):
            if u == -1:
                return
            path.append(val[u])
            total += val[u]
            if left[u] == -1 and right[u] == -1:
                if total == target:
                    results.append(list(path))
            else:
                dfs(left[u], path, total)
                dfs(right[u], path, total)
            path.pop()

        dfs(0, [], 0)
        out.append(str(len(results)))
        for r in results:
            out.append(' '.join(map(str, r)))
    print('\n'.join(out))

main()

import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); m = int(data[idx + 1]); idx += 2
        if n == 0 and m == 0:
            break
        adj = [[] for _ in range(n)]
        for _ in range(m):
            u = int(data[idx]); v = int(data[idx + 1]); idx += 2
            adj[u].append(v)
            adj[v].append(u)
        disc = [-1] * n
        low = [0] * n
        timer = [0]
        bridges = []

        def dfs(u, parent_edge):
            disc[u] = low[u] = timer[0]
            timer[0] += 1
            for v in adj[u]:
                if v == parent_edge:
                    continue
                if disc[v] == -1:
                    dfs(v, u)
                    low[u] = min(low[u], low[v])
                    if low[v] > disc[u]:
                        bridges.append(tuple(sorted((u, v))))
                else:
                    low[u] = min(low[u], disc[v])

        for i in range(n):
            if disc[i] == -1:
                dfs(i, -1)
        bridges.sort()
        out.append(str(len(bridges)))
        out.append(' '.join(f"({u},{v})" for u, v in bridges))
    print('\n'.join(out))

main()

import sys

def main():
    out = []
    for line in sys.stdin:
        s = line.strip()
        if not s:
            continue
        chars = list(s)
        stack = []
        for i, c in enumerate(chars):
            if c == '(':
                stack.append(i)
            elif c == ')':
                if stack:
                    stack.pop()
                else:
                    chars[i] = ''
        for i in stack:
            chars[i] = ''
        out.append(''.join(chars))
    print('\n'.join(out))

