import sys

def process(s):
    stack = []
    for c in s:
        if c == '#':
            if stack:
                stack.pop()
        else:
            stack.append(c)
    return ''.join(stack)

def main():
    out = []
    for line in sys.stdin:
        line = line.rstrip('\n')
        if not line:
            continue
        s, t = line.split()
        out.append('Yes' if process(s) == process(t) else 'No')
    print('\n'.join(out))

main()

import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); days = int(data[idx + 1]); idx += 2
        if n == 0 and days == 0:
            break
        weights = [int(data[idx + i]) for i in range(n)]
        idx += n

        def can_ship(cap):
            d = 1
            cur = 0
            for w in weights:
                if cur + w > cap:
                    d += 1
                    cur = 0
                cur += w
            return d <= days

        lo, hi = max(weights), sum(weights)
        while lo < hi:
            mid = (lo + hi) // 2
            if can_ship(mid):
                hi = mid
            else:
                lo = mid + 1
        out.append(str(lo))
    print('\n'.join(out))

main()

