import sys
import math

def main():
    data = sys.stdin.read().split()
    idx = 0
    out = []
    while idx < len(data):
        n = int(data[idx]); h = int(data[idx + 1]); idx += 2
        if n == 0 and h == 0:
            break
        piles = [int(data[idx + i]) for i in range(n)]
        idx += n

        def hours_needed(k):
            return sum(math.ceil(p / k) for p in piles)

        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            if hours_needed(mid) <= h:
                hi = mid
            else:
                lo = mid + 1
        out.append(str(lo))
    print('\n'.join(out))

main()

